const commands = [
  "uv run python - <<'PY'\nimport json\nfrom pathlib import Path\nroot=Path('reports/pilots/contact_p2')\nfor mode in ('gt_roi','detected_roi'):\n for split in ('val','test'):\n  p=root/f'predictions_{mode}_{split}.jsonl'\n  rows=[json.loads(x) for x in p.read_text().splitlines()]\n  rows.sort(key=lambda r:r['point_error_roi_diagonal_ratio'] or -1, reverse=True)\n  print('\\n',mode,split)\n  for r in rows[:4]: print(r['filename'], 'ratio=',round(r['point_error_roi_diagonal_ratio'],3), 'gt=',[round(x,1) for x in r['gt_point']], 'pred=',[round(x,1) for x in r['predicted_point']], 'roi=',[round(x,1) for x in r['roi']])\nPY",
  "find reports/pilots/contact_p2/preview/gt_roi/val -maxdepth 1 -type f -printf '%f\\n' | sort; find reports/pilots/contact_p2/preview/gt_roi/test -maxdepth 1 -type f -printf '%f\\n' | sort"
];
const res = await Promise.all(commands.map(command => tools.shell_command({
  command: `wsl.exe -d Ubuntu-24.04 --cd /home/lzttttt/mubiao--test -- bash -lc ${JSON.stringify(command)}`,
  workdir: "\\\\wsl.localhost\\Ubuntu-24.04\\home\\lzttttt\\mubiao--test",
  timeout_ms: 10000,
  sandbox_permissions: "require_escalated",
  justification: "允许我只读检查接触点评估中误差最大的样本与预览文件吗？",
  prefix_rule: ["wsl.exe","-d","Ubuntu-24.04","--cd","/home/lzttttt/mubiao--test","--","bash","-lc"]
})));
res.forEach(text);

