+Point2f decode_heatmap_peak_neighborhood(
+    const std::vector<float>& heatmap_logits,
+    std::size_t width,
+    std::size_t height,
+    const BBox& roi,
+    std::size_t radius) {
+    if (width == 0 || height == 0 || heatmap_logits.size() != width * height) {
+        throw std::invalid_argument("heatmap dimensions do not match its values");
+    }
+    const auto peak = std::max_element(heatmap_logits.begin(), heatmap_logits.end());
+    const std::size_t peak_index =
+        static_cast<std::size_t>(std::distance(heatmap_logits.begin(), peak));
+    const std::size_t peak_x = peak_index % width;
+    const std::size_t peak_y = peak_index / width;
+    const std::size_t start_x = peak_x > radius ? peak_x - radius : 0;
+    const std::size_t end_x = std::min(width, peak_x + radius + 1);
+    const std::size_t start_y = peak_y > radius ? peak_y - radius : 0;
+    const std::size_t end_y = std::min(height, peak_y + radius + 1);
+
+    double weight_sum = 0.0;
+    double weighted_x = 0.0;
+    double weighted_y = 0.0;
+    const double maximum = static_cast<double>(*peak);
+    for (std::size_t y = start_y; y < end_y; ++y) {
+        for (std::size_t x = start_x; x < end_x; ++x) {
+            const double weight =
+                std::exp(static_cast<double>(heatmap_logits[y * width + x]) - maximum);
+            weight_sum += weight;
+            weighted_x += weight * static_cast<double>(x);
+            weighted_y += weight * static_cast<double>(y);
+        }
+    }
+    if (!(weight_sum > 0.0) || !std::isfinite(weight_sum)) {
+        throw std::runtime_error("heatmap neighborhood softmax is not finite");
+    }
+    const double heatmap_x = weighted_x / weight_sum;
+    const double heatmap_y = weighted_y / weight_sum;
+    const double width_denominator =
