def _select_difficult_backtracking(
    specs,
    candidates: list[Candidate],
    core: list[Candidate],
) -> list[tuple[str, tuple[Candidate, Candidate]]]:
    prepared = []
    for difficulty, score in specs:
        pool = [
            item
            for item in candidates
            if item not in core and item.detector_score >= 0.05
        ]
        options = [
            pair
            for pair in itertools.combinations(pool, 2)
            if abs(pair[0].numeric_id - pair[1].numeric_id) >= 5
            and all(_far_enough(item, core) for item in pair)
        ]
        options.sort(key=lambda pair: sum(score(item) for item in pair), reverse=True)
        prepared.append((len(options), difficulty, options))
    prepared.sort(key=lambda value: value[0])

    def search(index: int, chosen: list[Candidate]):
        if index == len(prepared):
            return []
        _, difficulty, options = prepared[index]
        for pair in options:
