    raise RuntimeError("7860 和 7861 均被占用")


def _display_size(image: Image.Image) -> tuple[int, int]:
    scale = min(MAX_DISPLAY[0] / image.width, MAX_DISPLAY[1] / image.height, 1.0)
    return max(1, round(image.width * scale)), max(1, round(image.height * scale))


def _load():
    queue = read_manifest(MANIFEST_PATH)
    if len(queue) != 24:
        raise RuntimeError(f"多样性队列必须是24张，实际为{len(queue)}")
    boxes = load_bbox_records(PROJECT_ROOT)
    contact_rows = contacts.load_records(PROJECT_ROOT)
    box_index = {row["filename"]: index for index, row in enumerate(boxes)}
    contact_index = {row["filename"]: index for index, row in enumerate(contact_rows)}
    missing = [
        row["filename"]
        for row in queue
        if row["filename"] not in box_index or row["filename"] not in contact_index
    ]
    if missing:
        raise RuntimeError(f"队列图片未进入正式标签表：{missing}")
    return queue, boxes, contact_rows, box_index, contact_index


def _finished(row: dict[str, str], boxes, contacts_rows, box_index, contact_index) -> bool:
    filename = row["filename"]
    box = boxes[box_index[filename]]
    contact = contacts_rows[contact_index[filename]]
    return (
        row["review_state"] == "confirmed"
        and box["review_state"] == "confirmed"
        and contact["review_state"] == "confirmed"
    )


def _first_pending(queue, boxes, contact_rows, box_index, contact_index) -> int:
    for index, row in enumerate(queue):
        if not _finished(row, boxes, contact_rows, box_index, contact_index):
            return index
    return 0


